on></select></div><div class="overview-row"><span>Total Income</span><strong>{{ formatCurrency(salesTotal) }}</strong><b>↑ 12%</b><div class="spark"><i v-for="n in 8" :key="`s-${n}`" :style="{height: `${25 + ((n * 19) % 58)}%`}"></i></div></div><div class="overview-row"><span>Total Expenses</span><strong>{{ formatCurrency(expenseTotal) }}</strong><b>↓ 8%</b><div class="spark expense-spark"><i v-for="n in 8" :key="`se-${n}`" :style="{height: `${25 + ((n * 23) % 58)}%`}"></i></div></div><div class="overview-row"><span>Net Profit</span><strong>{{ formatCurrency(netProfit) }}</strong><b>↑ 28%</b><div class="spark"><i v-for="n in 8" :key="`sp-${n}`" :style="{height: `${20 + ((n * 17) % 62)}%`}"></i></div></div></article><article class="dashboard-card alerts-card"><div class="section-head"><h2><feather-icon name="bell" class="h-4 w-4"/>Alerts &amp; Reminders <i class="alert-count">{{ alerts.length }}</i></h2><button class="text-action">View All</button></div><button v-for="alert in alerts" :key="alert.text" class="alert-row" @click="routeTo(alert.path)"><span><feather-icon :name="alert.icon" class="h-3.5 w-3.5"/></span><div><b>{{ alert.text }}</b><small>{{ alert.detail }}</small></div><em>View</em></button><div v-if="!alerts.length" class="all-clear"><i>✓</i> Everything looks good.</div></article></aside></section>
