import { routeTo } from 'src/utils/ui';
import type { PeriodKey } from 'src/utils/types';

type InvoiceRow = { name: string; party: string; date: unknown; grandTotal: unknown; outstanding: number; status: string };
type BankAccount = { name: string; type: string; balance: number; review: boolean };
type AlertRow = { text: string; detail: string; path: string; icon: string };
export default { name:'Dashboard', components:{ Cashflow }, props:{ darkMode:{type:Boolean,default:false} }, data(){ return { period:'This Year' as PeriodKey, companyName:'', recentInvoices:[] as InvoiceRow[], bankAccounts:[] as BankAccount[], alerts:[] as AlertRow[], salesTotal:0, expenseTotal:0, bankBalance:0, reports:[{name:'Profit & Loss',detail:'Sep 1 – Sep 30, 2026',icon:'bar-chart-2',tone:'blue',path:'/report/ProfitAndLoss'},{name:'Balance Sheet',detail:'As of today',icon:'pie-chart',tone:'teal',path:'/report/BalanceSheet'},{name:'A/R Aging',detail:'Outstanding receivables',icon:'users',tone:'purple',path:'/report/AgingReceivable'},{name:'A/P Aging',detail:'Outstanding payables',icon:'briefcase',tone:'green',path:'/report/AgingPayable'}], cashFlowBars:[{label:'Operating',income:78,expense:88,value:18742},{label:'Investing',income:16,expense:22,value:2350},{label:'Financing',income:14,expense:24,value:1420}] }; }, computed:{ firstName(){ const name=this.$route.query?.name; return typeof name==='string'&&name?name:'there'; }, initials(){ return this.initialsFor(this.firstName); }, formattedDate(){ return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date()); }, netProfit(){ return this.salesTotal-this.expenseTotal; } }, async activated(){ docsPathRef.value='books/dashboard'; await this.loadDashboardData(); }, deactivated(){ docsPathRef.value=''; }, methods:{ routeTo, async loadDashboardData(){ this.companyName=(fyo.singles.AccountingSettings?.companyName as string)||''; const invoices=(await fyo.db.getAllRaw('SalesInvoice',{fields:['name','party','date','grandTotal','outstandingAmount','submitted','cancelled'],orderBy:'date',order:'desc',limit:8})) as Record<string,unknown>[]; this.recentInvoices=invoices.map((invoice)=>{const outstanding=Number(invoice.outstandingAmount??0);const cancelled=invoice.cancelled===true;const submitted=invoice.submitted===true;return{name:String(invoice.name??''),party:String(invoice.party??''),date:invoice.date,grandTotal:invoice.grandTotal,outstanding,status:cancelled?'Cancelled':!submitted?'Draft':outstanding>0?'Open':'Cleared'};}); const salesRows=(await fyo.db.getAllRaw('SalesInvoice',{fields:['grandTotal','submitted','cancelled','outstandingAmount']})) as Record<string,unknown>[]; this.salesTotal=salesRows.filter(r=>r.submitted===true&&r.cancelled!==true).reduce((s,r)=>s+Number(r.grandTotal??0),0); const purchaseRows=(await fyo.db.getAllRaw('PurchaseInvoice',{fields:['grandTotal','submitted','cancelled','outstandingAmount']})) as Record<string,unknown>[]; this.expenseTotal=purchaseRows.filter(r=>r.submitted===true&&r.cancelled!==true).reduce((s,r)=>s+Number(r.grandTotal??0),0); this.alerts=[]; const openInvoices=salesRows.filter(r=>r.submitted===true&&r.cancelled!==true&&Number(r.grandTotal??0)>0&&Number(r.outstandingAmount??0)>0); if(openInvoices.length)this.alerts.push({text:`${openInvoices.length} invoice${openInvoices.length===1?'':'s'} need follow-up`,detail:'Accounts Receivable',path:'/list/SalesInvoice',icon:'file-text'}); const openBills=purchaseRows.filter(r=>r.submitted===true&&r.cancelled!==true&&Number(r.outstandingAmount??0)>0); if(openBills.length)this.alerts.push({text:`${openBills.length} bill${openBills.length===1?'':'s'} is outstanding`,detail:'Accounts Payable',path:'/list/PurchaseInvoice',icon:'file-text'}); if(!this.alerts.length)this.alerts.push({text:'No outstanding reminders',detail:'Your books are up to date',path:'/report/ProfitAndLoss',icon:'check-circle'}); this.bankAccounts=[{name:'Operating Checking',type:'Business Account',balance:27415.5,review:false},{name:'Savings',type:'Savings',balance:12580.32,review:false},{name:'Payroll Account',type:'Payroll',balance:8240.17,review:false},{name:'Credit Card',type:'Visa Business',balance:-2314.26,review:true}]; this.bankBalance=this.bankAccounts.reduce((s,a)=>s+a.balance,0); }, handlePeriodChange(period:PeriodKey){this.period=period;}, async createDocument(schemaName:string){const doc=fyo.doc.getNewDoc(schemaName);await routeTo(`/edit/${schemaName}/${doc.name!}`);}, initialsFor(value:string){return value.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'CB';}, formatCurrency(value:unknown){return fyo.format(Number(value??0),'Currency');}, formatDate(value:unknown){if(!value)return'—';const date=new Date(value as string|number|Date);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat(undefined,{month:'2-digit',day:'2-digit',year:'numeric'}).format(date);} } };
